```javascript
const deleteArticle = async (req, res, next) => {
  try {
    const { loggedUser } = req;
    if (!loggedUser) throw new UnauthorizedError();

    const { slug } = req.params;
    const article = await Article.findOne({ slug }).lean();
    if (!article) throw new NotFoundError("Article");

    if (loggedUser._id !== article.authorId) throw new ForbiddenError("article");

    const session = await mongoose.startSession();
    await session.withTransaction(async () => {
      // Delete article
      await Article.deleteOne({ _id: article._id }, { session });

      // Delete related favorites
      const favRes = await Favorite.deleteMany(
        { "_id.articleId": article._id },
        { session }
      );

      // Decrement author's favoritesCount if any favorites were removed
      if (favRes.deletedCount > 0) {
        await User.updateOne(
          { _id: article.authorId },
          { $inc: { favoritesCount: -favRes.deletedCount } },
          { session }
        );
      }

      // Delete related comments
      await Comment.deleteMany({ articleId: article._id }, { session });
    });
    await session.endSession();

    res.json({ message: { body: ["Article deleted successfully"] } });
  } catch (error) {
    next(error);
  }
};
